<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class MedicalOfficeController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('medical_worker')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$q=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('student_medical_profiles as mp','mp.student_id','=','s.id')->where('s.status','active')->select('s.id','s.last_name','s.first_name','s.middle_name','g.name as group_name','mp.health_group','mp.physical_education_group');if($r->filled('q')){$x='%'.$r->q.'%';$q->where(fn($z)=>$z->where('s.last_name','like',$x)->orWhere('s.first_name','like',$x));}if($r->filled('group'))$q->where('s.current_group_id',$r->integer('group'));$rows=$q->orderBy('s.last_name')->get();$today=today();$soon=$today->copy()->addDays(30);$due=DB::table('student_medical_exams as x')->join('students as s','s.id','=','x.student_id')->where('s.status','active')->whereNotNull('x.next_exam_on')->whereBetween('x.next_exam_on',[$today,$soon])->select('x.*','s.last_name','s.first_name')->orderBy('x.next_exam_on')->get();$expired=DB::table('student_medical_exams as x')->join('students as s','s.id','=','x.student_id')->where('s.status','active')->whereNotNull('x.valid_until')->where('x.valid_until','<',$today)->select('x.*','s.last_name','s.first_name')->orderBy('x.valid_until')->get();$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();return view('medical.index',compact('rows','due','expired','groups'));}
 public function show(Request $r,$student){$this->ok($r);$s=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('s.id',$student)->select('s.*','g.name as group_name')->first();abort_if(!$s,404);return view('medical.student',['s'=>$s,'profile'=>DB::table('student_medical_profiles')->where('student_id',$student)->first(),'exams'=>DB::table('student_medical_exams')->where('student_id',$student)->orderByDesc('exam_on')->get(),'certificates'=>DB::table('student_medical_certificates')->where('student_id',$student)->orderByDesc('issued_on')->get()]);}
 public function profile(Request $r,$student){$this->ok($r);$d=$r->validate(['health_group'=>'nullable|string|max:100','physical_education_group'=>'nullable|string|max:100','limitations'=>'nullable|string|max:5000','allergies'=>'nullable|string|max:5000','dispensary_observation'=>'nullable|string|max:255','note'=>'nullable|string|max:5000']);DB::table('student_medical_profiles')->updateOrInsert(['student_id'=>$student],$d+['updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Медицинский профиль сохранён');}
 public function exam(Request $r,$student){$this->ok($r);$d=$r->validate(['exam_on'=>'required|date','exam_type'=>'required|string|max:100','organization'=>'nullable|string|max:255','result'=>'nullable|string|max:100','valid_until'=>'nullable|date','next_exam_on'=>'nullable|date','document_number'=>'nullable|string|max:100','recommendations'=>'nullable|string|max:5000']);DB::table('student_medical_exams')->insert($d+['student_id'=>$student,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Медосмотр зарегистрирован');}
 public function certificate(Request $r,$student){$this->ok($r);$d=$r->validate(['type'=>'required|string|max:100','number'=>'nullable|string|max:100','issued_on'=>'nullable|date','valid_from'=>'nullable|date','valid_until'=>'nullable|date|after_or_equal:valid_from','issuer'=>'nullable|string|max:255','note'=>'nullable|string|max:5000']);DB::table('student_medical_certificates')->insert($d+['student_id'=>$student,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Справка добавлена');}
}